type tokenContext struct {
	row    int
	start  int
	end    int
	prefix string
	token  string
}

type lineToken struct {
	start int
	end   int
	text  string
}

func scanLineTokens(line []rune) []lineToken {
	tokens := make([]lineToken, 0)
	col := 0
	for col < len(line) {
		for col < len(line) && unicode.IsSpace(line[col]) {
			col++
		}
		if col >= len(line) {
			break
		}

		start := col
		var quote rune
		escaped := false
		for col < len(line) {
			r := line[col]
			switch {
			case escaped:
				escaped = false
			case r == '\\' && quote != '\'':
				escaped = true
			case quote != 0:
				if r == quote {
					quote = 0
				}
			case r == '\'' || r == '"':
				quote = r
			case unicode.IsSpace(r):
				goto tokenDone
			}
			col++
		}
	tokenDone:
		tokens = append(tokens, lineToken{
			start: start,
			end:   col,
			text:  string(line[start:col]),
		})
	}
	return tokens
}

