		m.deleteDialog, cmd = m.deleteDialog.Update(msg)
		return m, cmd
	}

	if m.tabs.SelectedID() == "logs" {
		return m.handleLogKey(msg)
	}

	if m.editorScope.Active() {
		return m.handleDetailKey(msg)
	}
	if m.fm.Index() == 1 {
		return m.handleListKey(msg)
	}
	return m, nil

