func (m Model) Update(msg tea.Msg) (Model, tea.Cmd) {
	if next, cmd, handled := m.applyAction(msg); handled {
		return next, cmd
	}
	if !m.focused {
		return m, nil
	}
	key, ok := msg.(tea.KeyPressMsg)
	if !ok {
		return m, nil
	}
	switch key.String() {
	case "up", "k":
		m.selectRelative(-1)
	case "down", "j":
		m.selectRelative(1)
	case "pgup":
		m.selectRelative(-max(1, m.VisibleLines()))
	case "pgdown":
		m.selectRelative(max(1, m.VisibleLines()))
	case "home", "g":
		m.selectFirst()
	case "end", "G":
		m.selectLast()
	case "enter":
		return m, m.Activate()
	}
	return m, nil
}

